// OTHVM Streaks Tool — habit streaks registry + completions. No LLM.
const base = String($env.SUPABASE_URL ?? '');
const key = String($env.SUPABASE_SERVICE_KEY ?? '');
const TG = 'REPLACE_WITH_TELEGRAM_BOT_TOKEN';
const CHAT = 'REPLACE_WITH_TELEGRAM_CHAT_ID';
if (!base || !key) return [{ json: { ok: false, error: 'Supabase env vars missing in the n8n environment' } }];
const HB = { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Accept: 'application/json' };
const hreq = async (o) => {
  const opts = Object.assign({ returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 }, o);
  try { return await this.helpers.httpRequest(opts); } catch (e) { return { statusCode: 0, body: 'ERR ' + (e && e.message ? e.message : String(e)) }; }
};
const parse = (r) => { let d = r.body; if (typeof d === 'string' && d.length) { try { d = JSON.parse(d); } catch (e) {} } return { st: r.statusCode ?? 0, d }; };
const errOf = (r) => { const d = r.d; if (d && typeof d === 'object' && (d.message || d.hint)) return String(d.message) + (d.hint ? ' — ' + String(d.hint) : ''); return String(typeof d === 'string' ? d : JSON.stringify(d || '')).slice(0, 240); };
const cairoToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const input = $input.first().json || {};
const NAME = (v) => String(v == null ? '' : v).trim();
let op = NAME(input.operation);
if (op.indexOf('streaks.') === 0) op = op.slice(8);
const getRow = async (name) => {
  const r = parse(await hreq({ method: 'GET', url: base + '/rest/v1/streaks?select=*&name=eq.' + encodeURIComponent(name) + '&limit=1', headers: HB, json: true }));
  if (r.st > 0 && r.st < 300 && Array.isArray(r.d)) return { row: r.d[0] || null };
  return { row: null, err: errOf(r) };
};
const validTime = (t) => { const p = String(t).split(':'); return p.length === 2 && Number(p[0]) >= 0 && Number(p[0]) <= 23 && Number(p[1]) >= 0 && Number(p[1]) <= 59; };
const compact = (x) => ({ name: x.name, reminder_time: x.reminder_time, reminder_message: x.reminder_message, current_streak: x.current_streak, longest_streak: x.longest_streak, last_completed: x.last_completed, is_active: x.is_active });

try {
  if (op === 'list') {
    const r = parse(await hreq({ method: 'GET', url: base + '/rest/v1/streaks?select=*&order=created_at.asc', headers: HB, json: true }));
    if (r.st <= 0 || r.st >= 300 || !Array.isArray(r.d)) return [{ json: { ok: false, error: errOf(r) } }];
    return [{ json: { ok: true, count: r.d.length, streaks: r.d.map(compact) } }];
  }

  if (op === 'create') {
    const name = NAME(input.name);
    if (!name) return [{ json: { ok: false, error: 'name مطلوب' } }];
    const dup = await getRow(name);
    if (dup.err) return [{ json: { ok: false, error: dup.err } }];
    if (dup.row) return [{ json: { ok: false, error: 'في سلسلة بنفس الاسم بالفعل: ' + name } }];
    const time = NAME(input.reminder_time) || '19:00';
    if (!validTime(time)) return [{ json: { ok: false, error: 'reminder_time لازم يكون HH:MM بنظام 24 ساعة، مثال: 19:00' } }];
    const ins = parse(await hreq({ method: 'POST', url: base + '/rest/v1/streaks', headers: Object.assign({}, HB, { Prefer: 'return=representation' }), body: { name: name, reminder_time: time, reminder_message: NAME(input.reminder_message), current_streak: 0, longest_streak: 0 }, json: true }));
    if (ins.st <= 0 || ins.st >= 300) return [{ json: { ok: false, error: 'فشل إنشاء السلسلة: ' + errOf(ins) } }];
    const row = Array.isArray(ins.d) ? ins.d[0] : ins.d;
    return [{ json: { ok: true, streak: compact(row || { name: name, reminder_time: time, current_streak: 0, longest_streak: 0, is_active: true }) } }];
  }

  if (op === 'update') {
    const name = NAME(input.name);
    if (!name) return [{ json: { ok: false, error: 'name مطلوب' } }];
    const g = await getRow(name);
    if (g.err) return [{ json: { ok: false, error: g.err } }];
    if (!g.row) return [{ json: { ok: false, error: 'مفيش سلسلة بالاسم ده: ' + name } }];
    const patch = { updated_at: new Date().toISOString() };
    if (input.reminder_time !== undefined && NAME(input.reminder_time)) { if (!validTime(NAME(input.reminder_time))) return [{ json: { ok: false, error: 'reminder_time لازم يكون HH:MM' } }]; patch.reminder_time = NAME(input.reminder_time); }
    if (input.reminder_message !== undefined) patch.reminder_message = NAME(input.reminder_message);
    if (input.is_active !== undefined) patch.is_active = (input.is_active === true || String(input.is_active) === 'true');
    if (Object.keys(patch).length === 1) return [{ json: { ok: false, error: 'مفيش أي حقل للتعديل — ابعت reminder_time أو reminder_message أو is_active' } }];
    const up = parse(await hreq({ method: 'PATCH', url: base + '/rest/v1/streaks?name=eq.' + encodeURIComponent(name), headers: Object.assign({}, HB, { Prefer: 'return=representation' }), body: patch, json: true }));
    if (up.st <= 0 || up.st >= 300) return [{ json: { ok: false, error: errOf(up) } }];
    const row = Array.isArray(up.d) ? up.d[0] : up.d;
    return [{ json: { ok: true, streak: compact(row || {}) } }];
  }

  if (op === 'pause' || op === 'resume') {
    const name = NAME(input.name);
    if (!name) return [{ json: { ok: false, error: 'name مطلوب' } }];
    const g = await getRow(name);
    if (g.err) return [{ json: { ok: false, error: g.err } }];
    if (!g.row) return [{ json: { ok: false, error: 'مفيش سلسلة بالاسم ده: ' + name } }];
    const active = op === 'resume';
    const up = parse(await hreq({ method: 'PATCH', url: base + '/rest/v1/streaks?name=eq.' + encodeURIComponent(name), headers: Object.assign({}, HB, { Prefer: 'return=minimal' }), body: { is_active: active, updated_at: new Date().toISOString() }, json: true }));
    if (up.st <= 0 || up.st >= 300) return [{ json: { ok: false, error: errOf(up) } }];
    return [{ json: { ok: true, name: name, is_active: active } }];
  }

  if (op === 'delete') {
    const name = NAME(input.name);
    if (!name) return [{ json: { ok: false, error: 'name مطلوب' } }];
    const g = await getRow(name);
    if (g.err) return [{ json: { ok: false, error: g.err } }];
    if (!g.row) return [{ json: { ok: false, error: 'مفيش سلسلة بالاسم ده: ' + name } }];
    const del = parse(await hreq({ method: 'DELETE', url: base + '/rest/v1/streaks?name=eq.' + encodeURIComponent(name), headers: Object.assign({}, HB, { Prefer: 'return=minimal' }), json: true }));
    if (del.st <= 0 || del.st >= 300) return [{ json: { ok: false, error: errOf(del) } }];
    return [{ json: { ok: true, deleted: name, note: 'سجلات الأيام اتمسحت معاها تلقائياً' } }];
  }

  if (op === 'complete') {
    const name = NAME(input.name);
    if (!name) return [{ json: { ok: false, error: 'name مطلوب' } }];
    const g = await getRow(name);
    if (g.err) return [{ json: { ok: false, error: g.err } }];
    if (!g.row) return [{ json: { ok: false, error: 'مفيش سلسلة بالاسم ده: ' + name } }];
    const s = g.row;
    const today = cairoToday();
    const lr = parse(await hreq({ method: 'GET', url: base + '/rest/v1/streak_logs?select=status&streak_id=eq.' + encodeURIComponent(s.id) + '&log_date=eq.' + today + '&limit=1', headers: HB, json: true }));
    const existing = (lr.st > 0 && lr.st < 300 && Array.isArray(lr.d) && lr.d[0]) ? lr.d[0].status : null;
    if (existing === 'completed') return [{ json: { ok: true, already_today: true, name: name, current_streak: s.current_streak, longest_streak: s.longest_streak, message: 'مسجّلة بالفعل النهارده ✅ — سلسلة ' + name + ' زي ما هي ' + s.current_streak + ' يوم.' } }];
    const n = Number(s.current_streak || 0) + 1;
    const longest = Math.max(Number(s.longest_streak || 0), n);
    const up = parse(await hreq({ method: 'PATCH', url: base + '/rest/v1/streaks?id=eq.' + encodeURIComponent(s.id), headers: Object.assign({}, HB, { Prefer: 'return=minimal' }), body: { current_streak: n, longest_streak: longest, last_completed: today, updated_at: new Date().toISOString() }, json: true }));
    if (up.st <= 0 || up.st >= 300) return [{ json: { ok: false, error: errOf(up) } }];
    await hreq({ method: 'POST', url: base + '/rest/v1/streak_logs?on_conflict=streak_id,log_date', headers: Object.assign({}, HB, { Prefer: 'resolution=merge-duplicates,return=minimal' }), body: { streak_id: s.id, log_date: today, status: 'completed' }, json: true });
    return [{ json: { ok: true, name: name, current_streak: n, longest_streak: longest, last_completed: today, is_record: n === longest && n > 1, message: '🎉 تمام! سلسلة ' + name + ' بقت ' + n + ' يوم متواصلين — كمّل كده يا وحش! 🔥' } }];
  }

  if (op === 'status') {
    const name = NAME(input.name);
    if (!name) return [{ json: { ok: false, error: 'name مطلوب' } }];
    const g = await getRow(name);
    if (g.err) return [{ json: { ok: false, error: g.err } }];
    if (!g.row) return [{ json: { ok: false, error: 'مفيش سلسلة بالاسم ده: ' + name } }];
    const s = g.row;
    const lr = parse(await hreq({ method: 'GET', url: base + '/rest/v1/streak_logs?select=log_date,status&streak_id=eq.' + encodeURIComponent(s.id) + '&order=log_date.desc&limit=14', headers: HB, json: true }));
    const logs = (lr.st > 0 && lr.st < 300 && Array.isArray(lr.d)) ? lr.d : [];
    const today = cairoToday();
    const todayLog = logs.find((x) => x.log_date === today) || null;
    return [{ json: { ok: true, streak: compact(s), today: today, today_status: todayLog ? todayLog.status : null, recent_logs: logs } }];
  }

  return [{ json: { ok: false, error: 'عملية غير معروفة: "' + op + '". المتاح: list, create, update, pause, resume, delete, complete, status' } }];
} catch (e) {
  return [{ json: { ok: false, error: 'خطأ غير متوقع: ' + String(e && e.message ? e.message : e).slice(0, 300) } }];
}

// OTHVM — expand the generic params object into the flat fields the workflow expects.
const j = $json || {};
let p = j.params;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = {}; } }
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};
const out = Object.assign({}, p);
for (const k of ['operation', 'action', 'category']) {
  if (j[k] !== undefined && j[k] !== null && j[k] !== '') out[k] = j[k];
}
return [{ json: out }];
